package com.jadhavr.erp.account.service; import com.jadhavr.erp.account.dto.AccountDtos.*; import com.jadhavr.erp.audit.enums.*; import com.jadhavr.erp.audit.service.AuditLogService; import com.jadhavr.erp.auth.security.SecurityUtils; import com.jadhavr.erp.common.exception.*; import com.jadhavr.erp.user.entity.User; import com.jadhavr.erp.user.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class AccountService {private final UserRepository users;private final PasswordEncoder encoder;private final AuditLogService audit;public AccountService(UserRepository u,PasswordEncoder e,AuditLogService a){users=u;encoder=e;audit=a;}@Transactional(readOnly=true)public Profile me(){return map(user());}@Transactional public Profile update(UpdateProfile r){User u=user();u.setFullName(r.fullName().trim());u.setPhone(r.phone()==null||r.phone().isBlank()?null:r.phone().trim());users.save(u);audit.log(AuditModule.ACCOUNT,AuditAction.UPDATE,"User",u.getId(),"Updated own account profile");return map(u);}@Transactional public void change(ChangePassword r){if(!r.newPassword().equals(r.confirmPassword()))throw new BadRequestException("Password confirmation does not match");User u=user();if(!encoder.matches(r.currentPassword(),u.getPasswordHash()))throw new BadRequestException("Current password is incorrect");if(encoder.matches(r.newPassword(),u.getPasswordHash()))throw new BadRequestException("New password must be different from current password");u.setPasswordHash(encoder.encode(r.newPassword()));u.setMustChangePassword(false);users.save(u);audit.log(AuditModule.ACCOUNT,AuditAction.CHANGE_PASSWORD,"User",u.getId(),"Changed account password");}private User user(){return users.findById(SecurityUtils.getCurrentUserId()).orElseThrow(()->new ResourceNotFoundException("User not found"));}private Profile map(User u){var c=u.getCollege();return new Profile(u.getId(),c==null?null:c.getId(),c==null?null:c.getName(),c==null?null:c.getCode(),u.getFullName(),u.getEmail(),u.getPhone(),u.getStatus(),u.getRoles().stream().map(r->r.getName().name()).collect(java.util.stream.Collectors.toSet()),u.getLastLoginAt(),u.getCreatedAt(),u.getUpdatedAt());}}
